/// <summary>
/// UI Builder class for DocuHistory cleanup batch job.
/// Customizes the dialog behavior and query interaction.
/// </summary>
public class AVADocuHistoryCleanupUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField     dialogQueryName;
    AVADocuHistoryCleanupContract dataContract;
}

Method.Source:
/// <summary>
/// Builds the dialog.
/// </summary>
public void build()
{
    super();

    dataContract = this.dataContractObject() as AVADocuHistoryCleanupContract;
}

/// <summary>
/// Called after the dialog is built.
/// Adds query lookup button to allow users to modify the query.
/// </summary>
public void postBuild()
{
    super();

    dialogQueryName = this.bindInfo().getDialogField(
        this.dataContractObject(),
        methodStr(AVADocuHistoryCleanupContract, parmQueryName));

    if (dialogQueryName)
    {
        dialogQueryName.registerOverrideMethod(
            methodStr(FormStringControl, lookup),
            methodStr(AVADocuHistoryCleanupUIBuilder, queryNameLookup),
            this);
    }
}

/// <summary>
/// Lookup method for the query name field.
/// Opens the query dialog to allow users to modify the query criteria.
/// </summary>
/// <param name="_formStringControl">The form string control.</param>
private void queryNameLookup(FormStringControl _formStringControl)
{
    Query       query;
    QueryRun    queryRun;

    if (dataContract)
    {
        query = dataContract.getQuery();

        if (query)
        {
            queryRun = new QueryRun(query);

            if (queryRun.prompt())
            {
                dataContract.setQuery(queryRun.query());
                dataContract.parmQueryName(queryRun.query().name());
            }
        }
    }
}

/// <summary>
/// Retrieves values from the dialog before execution.
/// Ensures the query is properly stored in the contract.
/// </summary>
/// <returns>True if successful; otherwise, false.</returns>
public boolean getFromDialog()
{
    boolean ret;

    ret = super();

    // The query is already stored via the lookup method
    // Additional validation can be added here if needed

    return ret;
}
